contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address nonAdmin, string calldata desc) external {
        require(!c.isAdmin(nonAdmin), "caller must not be admin");
        bool reverted;
        try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function test(address nonAdmin, string calldata description) external {
        require(!c.isAdmin(nonAdmin), "pre: nonAdmin must not be admin");
        bool success;
        bytes memory ret;
        (success, ret) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));
        assert(success == c.isAdmin(nonAdmin));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, bool callerIsAdmin, string calldata description) public payable {
        require(callerIsAdmin == c.isAdmin(caller));
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted != callerIsAdmin);
    }
    receive() external payable {}
}

